<script setup lang="ts">
import {Sparkles,AlertTriangle,Clock3,MessageCircle} from 'lucide-vue-next'
const props=defineProps<{applicationId:string}>()
type Info={nextActions:{title:string;reason:string;url:string}[];forecast:{available:boolean;sampleSize:number;lowerDays?:number;upperDays?:number;activeCount?:number;basis?:string;reason?:string;deadline?:string};risk:{level:string;warnings:string[];notice:string};conflicts:{field:string;message:string;sources:string[]}[]}
const {data,error,pending,refresh}=await useFetch<Info>(()=>`/api/applications/${encodeURIComponent(props.applicationId)}/insights`,{key:`intelligent-case:${props.applicationId}`})
const question=ref('');const asking=ref(false);const askError=ref('');const answer=ref<{answer:string;sources:string[];notice:string}|null>(null)
async function ask(){if(question.value.trim().length<5||asking.value)return;asking.value=true;askError.value=''
 try{answer.value=await $fetch(`/api/applications/${encodeURIComponent(props.applicationId)}/ask`,{method:'POST',body:{question:question.value.trim()}})}catch(e){askError.value=readableError(e)}finally{asking.value=false}}
</script>
<template><section class="panel space-y-4 p-4 sm:p-5"><div class="flex items-center justify-between gap-2"><h3 class="flex items-center gap-2 font-extrabold"><Sparkles :size="20" class="text-brand-700"/>Hỗ trợ thông minh theo hồ sơ</h3><button class="btn-outline !text-xs" @click="refresh()">Cập nhật</button></div>
<p v-if="pending" class="text-sm">Đang đối chiếu dữ liệu...</p><p v-else-if="error" class="text-sm text-rose-700">Chưa tải được phân tích. Kiểm tra migration 17 và kết nối PostgreSQL.</p>
<template v-else-if="data"><div class="grid gap-3 lg:grid-cols-2"><div class="rounded-lg bg-blue-50 p-4"><p class="font-bold">Hành động tiếp theo</p><div v-for="a in data.nextActions" :key="a.url" class="mt-2"><NuxtLink :to="a.url" class="font-bold text-brand-700 underline">{{a.title}}</NuxtLink><p class="text-xs">{{a.reason}}</p></div></div><div class="rounded-lg bg-slate-50 p-4"><p class="flex items-center gap-2 font-bold"><Clock3 :size="17"/>Ước tính tiến độ</p><p v-if="data.forecast.available" class="mt-2 text-sm">Khoảng {{data.forecast.lowerDays}}–{{data.forecast.upperDays}} ngày lịch, từ {{data.forecast.sampleSize}} hồ sơ tương đồng (thống kê lịch sử). Hiện còn {{data.forecast.activeCount}} hồ sơ cùng thủ tục đang xử lý tại địa phương.</p><p v-else class="mt-2 text-sm text-muted">{{data.forecast.reason}}</p><p class="mt-2 text-xs text-muted">{{data.forecast.basis||'Không thay thế thời hạn xử lý theo quy định.'}}</p></div></div>
<div class="rounded-lg border border-amber-200 p-4"><p class="flex items-center gap-2 font-bold"><AlertTriangle :size="18"/>Cảnh báo rà soát: {{data.risk.level}}</p><ul v-if="data.risk.warnings.length" class="mt-2 list-disc space-y-1 pl-5 text-sm"><li v-for="(w,i) in data.risk.warnings" :key="i">{{w}}</li></ul><p v-else class="mt-2 text-sm text-muted">Chưa phát hiện lỗi theo các quy tắc đã cấu hình; không đảm bảo hồ sơ hợp lệ.</p><p v-if="data.conflicts.length" class="mt-2 text-xs text-amber-800">Đối chiếu giữa biểu mẫu và dữ liệu OCR đã được bạn xác nhận, có thể có ngoại lệ hợp pháp.</p><p class="mt-2 text-xs text-muted">{{data.risk.notice}}</p></div></template>
<div class="border-t pt-4"><h4 class="flex items-center gap-2 font-extrabold"><MessageCircle :size="18"/>Hỏi về hồ sơ của tôi</h4><p class="my-2 text-xs text-muted">Ví dụ: Hồ sơ đang ở bước nào? Cần bổ sung gì? Vì sao hồ sơ chưa hoàn thành?</p><form class="flex flex-wrap gap-2" @submit.prevent="ask"><input v-model="question" class="field min-w-0 flex-1" minlength="5" maxlength="500" placeholder="Nhập câu hỏi theo hồ sơ..." required/><button class="btn-primary" :disabled="asking||question.trim().length<5">{{asking?'Đang kiểm tra...':'Hỏi về hồ sơ'}}</button></form><p v-if="askError" class="mt-2 text-sm text-rose-700">{{askError}}</p><div v-if="answer" class="mt-3 rounded-lg bg-blue-50 p-3 text-sm"><p>{{answer.answer}}</p><p class="mt-2 text-xs text-muted">Nguồn: {{answer.sources.join(', ')}}. {{answer.notice}}</p></div></div>
</section></template>
